from __future__ import annotations
import argparse,pathlib,decimal,collections,time,hashlib,json
from common import save,load,db,query,csvwrite
from request_models import Request,VERSION
from engine import metric_sql,chart_sql,execute_metric
from contract_models import MODELS
def prepare(package):
    import pyarrow.parquet as pq
    p=pathlib.Path(package).resolve();m=load(p/'manifest.json')
    if m.get('p1_status')!='pass':raise ValueError('P1 gate must pass before P2 catalog creation')
    money=load(p/'evidence/p2_money.json');decimal.getcontext().prec=50;c=db(p)
    lines=pq.read_table(p/'data/raw/Sales.InvoiceLines.parquet').to_pylist();inv={r['InvoiceID']:r for r in pq.read_table(p/'data/raw/Sales.Invoices.parquet').to_pylist()};groups=collections.defaultdict(lambda:{'lines':0,'ex_tax':decimal.Decimal(0),'tax':decimal.Decimal(0),'extended':decimal.Decimal(0),'profit':decimal.Decimal(0),'exceptions':0,'rounding_exceptions':0})
    for r in lines:
        flag=inv[r['InvoiceID']]['IsCreditNote'];sign=(r['ExtendedPrice']>0)-(r['ExtendedPrice']<0);g=groups[(flag,sign)];g['lines']+=1;g['ex_tax']+=r['Quantity']*r['UnitPrice'];g['tax']+=r['TaxAmount'];g['extended']+=r['ExtendedPrice'];g['profit']+=r['LineProfit'];g['exceptions']+=int(r['ExtendedPrice']!=r['Quantity']*r['UnitPrice']+r['TaxAmount']);g['rounding_exceptions']+=int(r['TaxAmount']!=(r['Quantity']*r['UnitPrice']*r['TaxRate']/100).quantize(decimal.Decimal('0.01'),rounding=decimal.ROUND_HALF_UP))
    expected=[(flag,sign,g['lines'],g['ex_tax'],g['tax'],g['extended'],g['profit'],g['exceptions'],g['rounding_exceptions']) for (flag,sign),g in sorted(groups.items())]
    local=c.execute("SELECT i.IsCreditNote,sign(l.ExtendedPrice),COUNT(*),SUM(l.Quantity*l.UnitPrice),SUM(l.TaxAmount),SUM(l.ExtendedPrice),SUM(l.LineProfit),COUNT(*) FILTER(WHERE l.ExtendedPrice<>l.Quantity*l.UnitPrice+l.TaxAmount),COUNT(*) FILTER(WHERE l.TaxAmount<>ROUND(l.Quantity*l.UnitPrice*l.TaxRate*CAST(0.01 AS DECIMAL(3,2)),2)) FROM raw.Sales_Invoices i JOIN raw.Sales_InvoiceLines l USING(InvoiceID) GROUP BY 1,2 ORDER BY 1,2").fetchall()
    if local!=expected:raise ValueError('Independent monetary reconciliation differs')
    save(p/'evidence/candidates/money_independent.json',{'status':'pass-arithmetic','independent':'Python Decimal calculation from Parquet rows; no analytics/measure SQL shared','grouped_values':expected,'currency':'not present as explicit transaction currency in acquired schema; USD not assumed','M10':'blocked currency provenance','M11':'blocked currency provenance; recorded profit is not net profit','ordered_value_fallback':'arithmetic available, also blocked currency label; not substituted on dashboard'})
    base={'dataset_version':VERSION,'scenario_id':'base','supported_operations':['read_metric','read_records','read_chart','navigate_local_view','resolve_explicit_id'],'context_propagation':{'item':'retain explicit selected item across holdings/purchasing/supplier','period':'retain order-period intent; undated holdings do not apply dates and say so explicitly','scenario':'change resets entity selections and query scope','selection':'new selection replaces stale item/order/customer IDs','purchasing':'incoming vs all-history is explicit; related by item, not allocated'}}
    domain=[{'start':'2013-01-01','end':'2016-06-01','scenario_id':'base'},{'start':'2016-04-01','end':'2016-05-01','scenario_id':'base'},{'start':'2016-05-01','end':'2016-06-01','scenario_id':'base'},{'stock_item_id':80},{'stock_item_id':193},{'stock_group_id':'each exported group tested independently'}]
    definitions=[('M01','Orders created','How many orders were created?','distinct order','COUNT(DISTINCT OrderID)','orders','order_date',['Sales.Orders','Sales.OrderLines'],'verified','New backorders count as orders; not newly originating customer demand.'),('M02','Stored unpicked units','How many ordered units remain unpicked in the stored state?','order line','SUM(MAX(Quantity-PickedQuantity,0))','item units (count, unlike goods)','order_date',['Sales.Orders','Sales.OrderLines'],'verified','Not historical backlog, volume, available-to-promise or delivery failure.'),('M03','Orders with unpicked quantities','How many orders have at least one unpicked line?','distinct order','COUNT(DISTINCT OrderID WHERE positive remaining line)','orders','order_date',['Sales.Orders','Sales.OrderLines'],'verified','Distinct orders differ from lines.'),('M04','Stored holdings and reorder level','What stock is held for each selected item?','stock item','QuantityOnHand, ReorderLevel, TargetStockLevel','item units','none',['Warehouse.StockItemHoldings','Warehouse.StockItems'],'verified','Undated stored state; do not sum duplicated holdings or infer available stock.'),('M05','Related incoming units','What unreceived purchasing quantity is recorded under open flags?','purchase line','SUM((OrderedOuters-ReceivedOuters)*QuantityPerOuter) WHERE header/line nonfinalized and positive balance','item units (count, unlike goods)','purchase_order_date',['Purchasing.PurchaseOrders','Purchasing.PurchaseOrderLines','Warehouse.StockItems'],'verified','Actual PO supplier attribution; matching item does not establish customer allocation.'),('M06','Date-based time to pick completion','What is the elapsed time from date-only creation to final pick completion?','completed order','median(PickingCompletedWhen-date(OrderDate))','date-based hours','order_date',['Sales.Orders'],'candidate','Date-only start is not exact processing time; incomplete excluded; retained outside main charts.'),('M07','Recorded final receipt lateness','Does final receipt calendar date exceed stored expected date?','eligible fully received purchase line','LastReceiptDate > ExpectedDeliveryDate','lines / share','purchase_order_date',['Purchasing.PurchaseOrders','Purchasing.PurchaseOrderLines'],'candidate','Optional P3; final receipt and promise semantics require review.'),('M08','Recorded confirmation lateness','Does recorded confirmation calendar date exceed stored order expectation?','confirmed invoice','DATE(ConfirmedDeliveryTime)>ExpectedDeliveryDate','invoices / share','invoice_date',['Sales.Invoices','Sales.Orders'],'candidate','Optional P3; missing confirmation unknown; no causal guarantee.'),('M09','Estimated open lines','Can open lines be approximated at a historical boundary?','current surviving line','creation before boundary and completion after/unknown','estimated lines','order_date',['Sales.Orders','Sales.OrderLines'],'candidate','Optional P3; exact quantity history unavailable.'),('M10','Invoiced sales excluding tax','What recorded invoice-line amount excluding tax is stored?','invoice line','SUM(ExtendedPrice-TaxAmount)','unverified currency','invoice_date',['Sales.Invoices','Sales.InvoiceLines'],'blocked','Arithmetic reconciled; currency not established; excluded from dashboard.'),('M11','Recorded line profit','What profit value is recorded per invoice line?','invoice line','SUM(LineProfit)','unverified currency','invoice_date',['Sales.Invoices','Sales.InvoiceLines'],'blocked','Currency unresolved; not business net profit; excluded from dashboard.'),('M12_orders_category','Orders by current customer category','How are orders attributed to current sold-to customer categories?','distinct order by current category','COUNT(DISTINCT OrderID) grouped by current sold-to CustomerCategoryID','orders','order_date',['Sales.Orders','Sales.Customers','Sales.CustomerCategories'],'verified','Current classification, not historical segment membership; unknown explicit.')]
    measures=[]
    for mid,name,q,grain,formula,unit,basis,tables,status,limit in definitions:
        fs=['customer_id','stock_item_id','supplier_id','stock_group_id','order_id','order_line_id','status'] if mid in ['M01','M02','M03','M12_orders_category'] else ['stock_item_id','supplier_id','stock_group_id'] if mid=='M04' else ['stock_item_id','supplier_id','stock_group_id','purchase_order_id','purchase_line_id','status'] if mid=='M05' else []
        req=Request(date_basis=basis if basis in ['order_date','purchase_order_date','none'] else 'order_date')
        file=None
        if status=='verified':
            sql,params=metric_sql(mid,req);file='sql/local/'+mid+'.sql';(p/file).write_text(sql,encoding='utf-8');cols,rr=query(c,sql,params);csvwrite(p/'evidence/metrics'/f'{mid}.csv',cols,rr)
        measures.append({'id':mid,'name':name,'business_question':q,'grain':grain,'population':'selected stored sample scope; base-only default','formula':formula,'unit':unit,'currency':None,'date_basis':basis,'supported_filters':fs,'null_behavior':'Unknown dates excluded from dated intervals; remaining arithmetic fails if required quantities lost; lookup unknown category explicit','comparison_rule':'inclusive start/exclusive end; same metric/unit/date basis/scope; percent change null when previous=0','source_tables':tables,'query_file':file,'evidence_file':'evidence/metrics/'+mid+'.csv' if status=='verified' else 'evidence/candidates/revenue_reconciliation.csv' if mid in ['M10','M11'] else 'reports/measure_verdicts.md','status':status,'limitation':limit+' Validation is for recorded tested inputs, not every possible filter combination.','tested_domain':domain if status=='verified' else []})
    save(p/'catalog/measures.json',{**base,'items':measures})
    filters=[]
    for fid,typ,lookup in [('customer_id','integer','raw.Sales_Customers.CustomerID'),('stock_item_id','integer','analytics.items.StockItemID'),('supplier_id','integer','raw.Purchasing_Suppliers.SupplierID'),('stock_group_id','integer','raw.Warehouse_StockGroups.StockGroupID'),('order_id','integer','analytics.orders.OrderID'),('order_line_id','integer','analytics.order_lines.OrderLineID'),('purchase_line_id','integer','raw.Purchasing_PurchaseOrderLines.PurchaseOrderLineID'),('purchase_order_id','integer','raw.Purchasing_PurchaseOrders.PurchaseOrderID')]:filters.append({'id':fid,'views':['overview','fulfilment','supply','detail'],'field':fid,'date_basis':None,'operators':['eq'],'default':None,'value_type':typ,'valid_enums':[],'id_lookup':lookup,'propagation':'retain compatible explicit ID; unsupported metric/entity combination rejected','reset_rule':'new selection replaces previous value; scenario switch clears IDs'})
    for basis in ['order_date','expected_delivery_date','picking_completed_time','purchase_order_date']:
        filters.append({'id':basis,'views':['overview','fulfilment','supply','detail'],'field':'start/end','date_basis':basis,'operators':['gte','lt'],'default':'order_date' if basis=='order_date' else None,'value_type':'ISO-date pair','valid_enums':[],'id_lookup':None,'propagation':'preserve declared basis and period; invoice/confirmation are acquired but not exposed as money operations; unsupported combinations reject','reset_rule':'undated holdings: show retained intent separately; active dates omitted explicitly'})
    filters.append({'id':'status','views':['overview','fulfilment','supply','detail'],'field':'status','date_basis':None,'operators':['eq'],'default':'all','value_type':'enum','valid_enums':['all','quantity-not-yet-picked','picking-incomplete','picking-complete','incoming','all-history'],'id_lookup':None,'propagation':'explicitly chosen status; purchasing vs sales mismatch rejects','reset_rule':'navigation from order investigation to incoming purchase evidence changes status to incoming visibly'})
    save(p/'catalog/filters.json',{**base,'items':filters})
    specs=[('monthly-orders','Monthly orders created','overview','M01','order_date','month','orders','calendar month ascending','order records in selected month'),('category-orders','Orders by current customer category','overview','M12_orders_category','order_date','current category','orders','category ascending','customer/order records'),('top-unpicked','Items by stored unpicked units','fulfilment','M02','order_date','stock item','unpicked item units','units descending; item ID tie break','item and contributing order lines'),('picking-status','Picking status of created orders','fulfilment','M01','order_date','order picking status','distinct orders','label ascending','orders filtered by completion stamp'),('holdings-reorder','Stored holdings and reorder level','supply','M04','none','stock item','item units','item ID ascending','stock item detail'),('incoming-supplier','Related incoming units by actual supplier','supply','M05','purchase_order_date','actual supplier','item units (count)','units descending; supplier ID tie break','purchase lines and supplier')]
    charts=[];widgets=[]
    for cid,title,view,mid,basis,x,y,sort,drill in specs:
        req=Request(date_basis=basis,limit=20 if cid=='top-unpicked' else 50);sql,params=chart_sql(cid,req);file='sql/local/chart_'+cid+'.sql';(p/file).write_text(sql,encoding='utf-8');cols,rr=query(c,sql,params);ef='evidence/charts/'+cid+'.csv';csvwrite(p/ef,cols,rr)
        caption=('Stored sample state. ' if mid in ['M02','M04','M05'] else '')+('Unlike item units are count totals, not physical volume or money. ' if mid in ['M02','M05'] else '')+('Current sold-to customer classification. ' if cid=='category-orders' else '')+'Date basis: '+basis+'. Related purchase lines are not customer allocations.'
        charts.append({'id':cid,'title':title,'widget_id':cid,'measure_id':mid,'query_file':file,'evidence_file':ef,'axes':{'x':x,'y':y},'sorting':[sort],'comparison':'only same unit, grain, period basis and scenario; zero denominator -> unknown percent change','drill_down':drill,'caption':caption})
        widgets.append({'id':cid,'type':'chart','view_id':view,'query_id':cid,'measure_id':mid,'display_unit':y,'filters':next(x['supported_filters'] for x in measures if x['id']==mid),'record_links':['customer','order','order-line','item','purchase','purchase-line','supplier'],'loading':'Loading verified data…','empty':'No matching source records under the applied scope','error':'Display validation/query failure; do not show stale values as completed'})
    for wid,view,mid in [('order-card','overview','M01'),('unpicked-orders-card','overview','M03'),('unpicked-units-card','fulfilment','M02'),('incoming-card','supply','M05')]:widgets.append({'id':wid,'type':'metric','view_id':view,'query_id':mid,'measure_id':mid,'display_unit':next(x['unit'] for x in measures if x['id']==mid),'filters':next(x['supported_filters'] for x in measures if x['id']==mid),'record_links':['order','item','purchase'],'loading':'Loading','empty':'Zero matching records','error':'Visible failure and cleared stale result'})
    save(p/'catalog/charts.json',{**base,'items':charts});save(p/'catalog/widgets.json',{**base,'items':widgets})
    views=[{'id':v,'route':'#/'+v,'url_parameters':['scenario_id','date_basis','start','end','customer_id','stock_item_id','supplier_id'],'widgets':[w['id'] for w in widgets if w['view_id']==v],'detail_destinations':['#/customer/{id}','#/order/{id}','#/order-line/{id}','#/item/{id}','#/purchase/{id}','#/purchase-line/{id}','#/supplier/{id}'],'integration_status':'local companion implementation; no no-code platform API claimed'} for v in ['overview','fulfilment','supply']]
    save(p/'catalog/views.json',{**base,'items':views});save(p/'catalog/contract_version.json',{**base,'contract_version':'0.1.0','query_catalog_version':'v1','schema_version':'pydantic-v0','supported_scenario_ids':['base','no_incoming_v1']})
    # Independently check current-category order attribution.
    cats={r['CustomerCategoryID']:r['CustomerCategoryName'] for r in pq.read_table(p/'data/raw/Sales.CustomerCategories.parquet').to_pylist()};customers={r['CustomerID']:r for r in pq.read_table(p/'data/raw/Sales.Customers.parquet').to_pylist()};oc=collections.Counter(cats.get(customers[r['CustomerID']]['CustomerCategoryID'],'unknown') for r in pq.read_table(p/'data/raw/Sales.Orders.parquet').to_pylist());actual=c.execute((p/'sql/local/M12_orders_category.sql').read_text(),['base']).fetchall()
    if dict(actual)!=dict(oc):raise ValueError('Independent segmentation mismatch')
    save(p/'evidence/candidates/segment_independent.json',{'status':'pass','orders_by_current_sold_to_category':dict(oc),'sum':sum(oc.values()),'share_denominator':sum(oc.values()),'shares':{k:str(decimal.Decimal(v)/sum(oc.values())) for k,v in oc.items()}})
    times=[]
    for mid in METRIC_IDS:
        basis=next(x['date_basis'] for x in measures if x['id']==mid);r=Request(date_basis=basis)
        for i in range(3):
            st=time.perf_counter();result=execute_metric(p,mid,r);payload=json.dumps(result['rows'],sort_keys=True,default=str).encode();times.append({'measure_id':mid,'run':i+1,'wall_seconds':time.perf_counter()-st,'rows':len(result['rows']),'sha256':hashlib.sha256(payload).hexdigest()})
    save(p/'evidence/metric_timings.json',times);c.close();print('P2 catalog prepared; monetary arithmetic reconciled, currency blocked',flush=True)
METRIC_IDS=['M01','M02','M03','M04','M05','M12_orders_category']
if __name__=='__main__':
    ap=argparse.ArgumentParser();ap.add_argument('--package',required=True);a=ap.parse_args();prepare(a.package)

